export const getAuthorizeRoute = createRoute({
  method: 'get',
  path: '/authorize',
  tags: ['Authorization'],
  summary: 'Authorize user',
  description:
    "Authorize a user by sending them through the [Box](https://box.com)\nwebsite and request their permission to act on their behalf.\n\nThis is the first step when authenticating a user using\nOAuth 2.0. To request a user's authorization to use the Box APIs\non their behalf you will need to send a user to the URL with this\nformat.",
  operationId: 'get_authorize',
  request: {
    query: z.object({
      response_type: z
        .literal('code')
        .openapi({
          param: {
            description: "The type of response we'd like to receive.",
            example: 'code',
            in: 'query',
            name: 'response_type',
            required: true,
            schema: { enum: ['code'], format: 'token', type: 'string' },
          },
        }),
      client_id: z
        .string()
        .openapi({
          param: {
            description:
              "The Client ID of the application that is requesting to authenticate\nthe user. To get the Client ID for your application, log in to your\nBox developer console and click the **Edit Application** link for\nthe application you're working with. In the OAuth 2.0 Parameters section\nof the configuration page, find the item labelled `client_id`. The\ntext of that item is your application's Client ID.",
            example: 'ly1nj6n11vionaie65emwzk575hnnmrk',
            in: 'query',
            name: 'client_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
      redirect_uri: z
        .url()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The URI to which Box redirects the browser after the user has granted\nor denied the application permission. This URI match one of the redirect\nURIs in the configuration of your application. It must be a\nvalid HTTPS URI and it needs to be able to handle the redirection to\ncomplete the next step in the OAuth 2.0 flow.\nAlthough this parameter is optional, it must be a part of the\nauthorization URL if you configured multiple redirect URIs\nfor the application in the developer console. A missing parameter causes\na `redirect_uri_missing` error after the user grants application access.',
            example: 'http://example.com/auth/callback',
            in: 'query',
            name: 'redirect_uri',
            required: false,
            schema: { format: 'url', type: 'string' },
          },
        }),
      state: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'A custom string of your choice. Box will pass the same string to\nthe redirect URL when authentication is complete. This parameter\ncan be used to identify a user on redirect, as well as protect\nagainst hijacked sessions and other exploits.',
            example: 'my_state',
            in: 'query',
            name: 'state',
            required: false,
            schema: { type: 'string' },
          },
        }),
      scope: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "A comma-separated list of application scopes you'd like to\nauthenticate the user for. This defaults to all the scopes configured\nfor the application in its configuration page.",
            example: 'admin_readwrite',
            in: 'query',
            name: 'scope',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Does not return any data, but rather should be used in the browser.',
      content: { 'text/html': { schema: z.string() } },
    },
    default: {
      description: 'Does not return any data, but rather should be used in the browser.',
      content: { 'text/html': { schema: z.string() } },
    },
  },
  security: [],
  servers: [
    {
      description: 'Server for client-side authentication',
      url: 'https://account.box.com/api/oauth2',
    },
  ],
})

export const getCollaborationWhitelistEntriesRoute = createRoute({
  method: 'get',
  path: '/collaboration_whitelist_entries',
  tags: ['Domain restrictions for collaborations'],
  summary: 'List allowed collaboration domains',
  description:
    'Returns the list domains that have been deemed safe to create collaborations\nfor within the current enterprise.',
  operationId: 'get_collaboration_whitelist_entries',
  request: {
    query: z.object({
      marker: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Defines the position marker at which to begin returning results. This is\nused when paginating using marker-based pagination.\n\nThis requires `usemarker` to be set to `true`.',
            example: 'JV9IRGZmieiBasejOG9yDCRNgd2ymoZIbjsxbJMjIs3kioVii',
            in: 'query',
            name: 'marker',
            required: false,
            schema: { type: 'string' },
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            example: 1000,
            in: 'query',
            name: 'limit',
            required: false,
            schema: { format: 'int64', maximum: 1000, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returns a collection of domains that are allowed for collaboration.',
      content: { 'application/json': { schema: CollaborationAllowlistEntriesSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

