export const postCollaborationsRoute = createRoute({
  method: 'post',
  path: '/collaborations',
  tags: ['Collaborations'],
  summary: 'Create collaboration',
  description:
    "Adds a collaboration for a single user or a single group to a file\nor folder.\n\nCollaborations can be created using email address, user IDs, or a\ngroup IDs.\n\nIf a collaboration is being created with a group, access to\nthis endpoint is dependent on the group's ability to be invited.",
  operationId: 'post_collaborations',
  request: {
    query: z.object({
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.',
            example: ['id', 'type', 'name'],
            explode: false,
            in: 'query',
            name: 'fields',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
          },
        }),
      notify: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Determines if users should receive email notification\nfor the action performed.',
            example: true,
            in: 'query',
            name: 'notify',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              accessible_by: z
                .object({
                  id: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'The ID of the user or group.\n\nAlternatively, use `login` to specify a user by email\naddress.',
                      example: '23522323',
                    }),
                  login: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'The email address of the user to grant access to the item.\n\nAlternatively, use `id` to specify a user by user ID.',
                      example: 'john@example.com',
                    }),
                  type: z
                    .enum(['user', 'group'])
                    .openapi({
                      description: 'The type of collaborator to invite.',
                      example: 'user',
                    }),
                })
                .openapi({
                  description: 'The user or group to give access to the item.',
                  required: ['type'],
                }),
              can_view_path: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    "Determines if the invited users can see the entire parent path to\nthe associated folder. The user will not gain privileges in any\nparent folder and therefore can not see content the user is not\ncollaborated on.\n\nBe aware that this meaningfully increases the time required to load the\ninvitee's **All Files** page. We recommend you limit the number of\ncollaborations with `can_view_path` enabled to 1,000 per user.\n\nOnly owner or co-owners can invite collaborators with a `can_view_path` of\n`true`.\n\n`can_view_path` can only be used for folder collaborations.",
                  example: true,
                }),
              expires_at: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({
                  description:
                    'Set the expiration date for the collaboration. At this date, the\ncollaboration will be automatically removed from the item.\n\nThis feature will only work if the **Automatically remove invited\ncollaborators: Allow folder owners to extend the expiry date**\nsetting has been enabled in the **Enterprise Settings**\nof the **Admin Console**. When the setting is not enabled,\ncollaborations can not have an expiry date and a value for this\nfield will be result in an error.',
                  example: '2019-08-29T23:59:00-07:00',
                }),
              item: z
                .object({
                  id: z
                    .string()
                    .openapi({
                      description: 'The ID of the item that will be granted access to',
                      example: '11446498',
                    }),
                  type: z
                    .enum(['file', 'folder'])
                    .openapi({
                      description:
                        'The type of the item that this collaboration will be\ngranted access to',
                      example: 'file',
                    }),
                })
                .openapi({
                  description: 'The item to attach the comment to.',
                  required: ['id', 'type'],
                }),
              role: z
                .enum([
                  'editor',
                  'viewer',
                  'previewer',
                  'uploader',
                  'previewer uploader',
                  'viewer uploader',
                  'co-owner',
                ])
                .openapi({ description: 'The level of access granted.', example: 'editor' }),
            })
            .openapi({ required: ['item', 'accessible_by', 'role'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Returns a new collaboration object.',
      content: { 'application/json': { schema: CollaborationSchema } },
    },
    403: {
      description:
        'Returns an error when the user does not have the\nright permissions to create the collaboration.\n\n* `forbidden_by_policy`: Creating a\ncollaboration is forbidden due to information\nbarrier restrictions.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

