export const getFileVersionLegalHoldsRoute = createRoute({
  method: 'get',
  path: '/file_version_legal_holds',
  tags: ['File version legal holds'],
  summary: 'List file version legal holds',
  description:
    'Get a list of file versions on legal hold for a legal hold\nassignment.\n\nDue to ongoing re-architecture efforts this API might not return all file\nversions for this policy ID.\n\nInstead, this API will only return file versions held in the legacy\narchitecture. Two new endpoints will available to request any file versions\nheld in the new architecture.\n\nFor file versions held in the new architecture, the `GET\n/legal_hold_policy_assignments/:id/file_versions_on_hold` API can be used to\nreturn all past file versions available for this policy assignment, and the\n`GET /legal_hold_policy_assignments/:id/files_on_hold` API can be used to\nreturn any current (latest) versions of a file under legal hold.\n\nThe `GET /legal_hold_policy_assignments?policy_id={id}` API can be used to\nfind a list of policy assignments for a given policy ID.\n\nOnce the re-architecture is completed this API will be deprecated.',
  operationId: 'get_file_version_legal_holds',
  request: {
    query: z.object({
      policy_id: z
        .string()
        .openapi({
          param: {
            description:
              'The ID of the legal hold policy to get the file version legal\nholds for.',
            example: '133870',
            in: 'query',
            name: 'policy_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
      marker: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Defines the position marker at which to begin returning results. This is\nused when paginating using marker-based pagination.\n\nThis requires `usemarker` to be set to `true`.',
            example: 'JV9IRGZmieiBasejOG9yDCRNgd2ymoZIbjsxbJMjIs3kioVii',
            in: 'query',
            name: 'marker',
            required: false,
            schema: { type: 'string' },
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            example: 1000,
            in: 'query',
            name: 'limit',
            required: false,
            schema: { format: 'int64', maximum: 1000, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returns the list of file version legal holds for a specific legal\nhold policy.',
      content: { 'application/json': { schema: FileVersionLegalHoldsSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

