export const postFilesUploadSessionsRoute = createRoute({
  method: 'post',
  path: '/files/upload_sessions',
  tags: ['Uploads (Chunked)'],
  summary: 'Create upload session',
  description: 'Creates an upload session for a new file.',
  operationId: 'post_files_upload_sessions',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              file_name: z
                .string()
                .openapi({ description: 'The name of new file', example: 'Project.mov' }),
              file_size: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description: 'The total number of bytes of the file to be uploaded',
                  example: 104857600,
                }),
              folder_id: z
                .string()
                .openapi({
                  description: 'The ID of the folder to upload the new file to.',
                  example: '0',
                }),
            })
            .openapi({ required: ['folder_id', 'file_size', 'file_name'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Returns a new upload session.',
      content: { 'application/json': { schema: UploadSessionSchema } },
    },
    400: {
      description:
        'Returns an error if some of the parameters are missing or\nnot valid.\n\n* `missing_destination`: No `folder_id` was provided\n* `invalid_folder_id`: `folder_id` is not valid\n* `item_name_invalid`: `file_name` is not valid\n* `missing_file_size`: `file_size` was not provided\n* `invalid_file_size`: `file_size` was not a valid number\n* `file_size_too_small`: `file_size` is below minimum file size for\n  uploads via this API\n* `missing_file_name`: `file_name` was not provided',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    403: {
      description:
        'Returns an error if the operation is not allowed for some reason.\n\n* `storage_limit_exceeded`: Account storage limit reached',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    404: {
      description:
        'Returns an error if the parent folder could not be found, or\nthe authenticated user does not have access to it.\n\n* `invalid_parameter`: The `folder_id` value represents a\n  folder that the user does not have access to, or does not\n  exist.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    409: {
      description:
        'Returns an error if the file already exists,\nor the account has run out of disk space.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
  servers: [{ description: 'Server for file uploads', url: 'https://upload.box.com/api/2.0' }],
})

