export const putFilesUploadSessionsUploadSessionIdRoute = createRoute({
  method: 'put',
  path: '/files/upload_sessions/{upload_session_id}',
  tags: ['Uploads (Chunked)'],
  summary: 'Upload part of file',
  description: 'Updates a chunk of an upload session for a file.',
  operationId: 'put_files_upload_sessions_id',
  request: {
    params: z.object({
      upload_session_id: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the upload session.',
            example: 'D5E3F7A',
            in: 'path',
            name: 'upload_session_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    headers: z.object({
      digest: z
        .string()
        .openapi({
          param: {
            description:
              'The [RFC3230][1] message digest of the chunk uploaded.\n\nOnly SHA1 is supported. The SHA1 digest must be base64\nencoded. The format of this header is as\n`sha=BASE64_ENCODED_DIGEST`.\n\nTo get the value for the `SHA` digest, use the\nopenSSL command to encode the file part:\n`openssl sha1 -binary <FILE_PART_NAME> | base64`\n\n[1]: https://tools.ietf.org/html/rfc3230',
            example: 'sha=fpRyg5eVQletdZqEKaFlqwBXJzM=',
            in: 'header',
            name: 'digest',
            required: true,
            schema: { type: 'string' },
          },
        }),
      'content-range': z
        .string()
        .openapi({
          param: {
            description:
              "The byte range of the chunk.\n\nMust not overlap with the range of a part already\nuploaded this session. Each part’s size must be\nexactly equal in size to the part size specified\nin the upload session that you created.\nOne exception is the last part of the file, as this can be smaller.\n\nWhen providing the value for `content-range`, remember that:\n\n* The lower bound of each part's byte range\n  must be a multiple of the part size.\n* The higher bound must be a multiple of the part size - 1.",
            example: 'bytes 8388608-16777215/445856194',
            in: 'header',
            name: 'content-range',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/octet-stream': {
          schema: z
            .file()
            .openapi({
              type: 'string',
              format: 'binary',
              description: 'The binary content of the file',
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Chunk has been uploaded successfully.',
      content: { 'application/json': { schema: UploadedPartSchema } },
    },
    409: {
      description:
        'Returns an error if the chunk conflicts with another\nchunk previously uploaded.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    412: {
      description: 'Returns an error if a precondition was not met.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    416: {
      description:
        'Returns an error if the content range does not match a specified range\nfor the session.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
  servers: [{ description: 'Server for file uploads', url: 'https://upload.box.com/api/2.0' }],
})

