export const postFilesUploadSessionsUploadSessionIdCommitRoute = createRoute({
  method: 'post',
  path: '/files/upload_sessions/{upload_session_id}/commit',
  tags: ['Uploads (Chunked)'],
  summary: 'Commit upload session',
  description: 'Close an upload session and create a file from the\nuploaded chunks.',
  operationId: 'post_files_upload_sessions_id_commit',
  request: {
    params: z.object({
      upload_session_id: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the upload session.',
            example: 'D5E3F7A',
            in: 'path',
            name: 'upload_session_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    headers: z.object({
      digest: z
        .string()
        .openapi({
          param: {
            description:
              'The [RFC3230][1] message digest of the whole file.\n\nOnly SHA1 is supported. The SHA1 digest must be Base64\nencoded. The format of this header is as\n`sha=BASE64_ENCODED_DIGEST`.\n\n[1]: https://tools.ietf.org/html/rfc3230',
            example: 'sha=fpRyg5eVQletdZqEKaFlqwBXJzM=',
            in: 'header',
            name: 'digest',
            required: true,
            schema: { type: 'string' },
          },
        }),
      'if-match': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "Ensures this item hasn't recently changed before\nmaking changes.\n\nPass in the item's last observed `etag` value\ninto this header and the endpoint will fail\nwith a `412 Precondition Failed` if it\nhas changed since.",
            example: '1',
            in: 'header',
            name: 'if-match',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'if-none-match': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "Ensures an item is only returned if it has changed.\n\nPass in the item's last observed `etag` value\ninto this header and the endpoint will fail\nwith a `304 Not Modified` if the item has not\nchanged since.",
            example: '1',
            in: 'header',
            name: 'if-none-match',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              parts: z
                .array(UploadPartSchema)
                .openapi({ description: 'The list details for the uploaded parts' }),
            })
            .openapi({ required: ['parts'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Returns the file object in a list.',
      content: { 'application/json': { schema: FilesSchema } },
    },
    202: {
      description:
        'Returns when all chunks have been uploaded but not yet processed.\n\nInspect the upload session to get more information about the\nprogress of processing the chunks, then retry committing the file\nwhen all chunks have processed.',
      headers: z.object({
        'Retry-After': {
          description:
            'Indicates the number of seconds the client should wait before\nattempting their commit request again.',
          schema: z
            .int()
            .exactOptional()
            .openapi({
              description:
                'Indicates the number of seconds the client should wait before\nattempting their commit request again.',
              param: { required: false },
            }),
        },
      }),
    },
    409: {
      description:
        'Returns an error if there is already a file with the same name\nin the target folder.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    412: {
      description: 'Returns an error if the `If-Match` or `If-None-Match` conditions fail.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
  servers: [{ description: 'Server for file uploads', url: 'https://upload.box.com/api/2.0' }],
})

export const getFilesUploadSessionsUploadSessionIdPartsRoute = createRoute({
  method: 'get',
  path: '/files/upload_sessions/{upload_session_id}/parts',
  tags: ['Uploads (Chunked)'],
  summary: 'List parts',
  description: 'Return a list of the chunks uploaded to the upload\nsession so far.',
  operationId: 'get_files_upload_sessions_id_parts',
  request: {
    params: z.object({
      upload_session_id: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the upload session.',
            example: 'D5E3F7A',
            in: 'path',
            name: 'upload_session_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The offset of the item at which to begin the response.\n\nQueries with offset parameter value\nexceeding 10000 will be rejected\nwith a 400 response.',
            example: 1000,
            in: 'query',
            name: 'offset',
            required: false,
            schema: { default: 0, format: 'int64', type: 'integer' },
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            example: 1000,
            in: 'query',
            name: 'limit',
            required: false,
            schema: { format: 'int64', maximum: 1000, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returns a list of parts that have been uploaded.',
      content: { 'application/json': { schema: UploadPartsSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
  servers: [{ description: 'Server for file uploads', url: 'https://upload.box.com/api/2.0' }],
})

export const getFilesFileIdRoute = createRoute({
  method: 'get',
  path: '/files/{file_id}',
  tags: ['Files'],
  summary: 'Get file information',
  description: 'Retrieves the details about a file.',
  operationId: 'get_files_id',
  request: {
    params: z.object({
      file_id: z
        .string()
        .openapi({
          param: {
            description:
              'The unique identifier that represents a file.\n\nThe ID for any file can be determined\nby visiting a file in the web application\nand copying the ID from the URL. For example,\nfor the URL `https://*.app.box.com/files/123`\nthe `file_id` is `123`.',
            example: '12345',
            in: 'path',
            name: 'file_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.\n\nAdditionally this field can be used to query any metadata\napplied to the file by specifying the `metadata` field as well\nas the scope and key of the template to retrieve, for example\n`?field=metadata.enterprise_12345.contractTemplate`.',
            example: ['id', 'type', 'name'],
            explode: false,
            in: 'query',
            name: 'fields',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
          },
        }),
    }),
    headers: z.object({
      'if-none-match': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "Ensures an item is only returned if it has changed.\n\nPass in the item's last observed `etag` value\ninto this header and the endpoint will fail\nwith a `304 Not Modified` if the item has not\nchanged since.",
            example: '1',
            in: 'header',
            name: 'if-none-match',
            required: false,
            schema: { type: 'string' },
          },
        }),
      boxapi: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The URL, and optional password, for the shared link of this item.\n\nThis header can be used to access items that have not been\nexplicitly shared with a user.\n\nUse the format `shared_link=[link]` or if a password is required then\nuse `shared_link=[link]&shared_link_password=[password]`.\n\nThis header can be used on the file or folder shared, as well as on any files\nor folders nested within the item.',
            example: 'shared_link=[link]&shared_link_password=[password]',
            in: 'header',
            name: 'boxapi',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'x-rep-hints': z
        .string()
        .nullable()
        .openapi({
          param: {
            description:
              'A header required to request specific `representations`\nof a file. Use this in combination with the `fields` query\nparameter to request a specific file representation.\n\nThe general format for these representations is\n`X-Rep-Hints: [...]` where `[...]` is one or many\nhints in the format `[fileType?query]`.\n\nFor example, to request a `png` representation in `32x32`\nas well as `64x64` pixel dimensions provide the following\nhints.\n\n`x-rep-hints: [jpg?dimensions=32x32][jpg?dimensions=64x64]`\n\nAdditionally, a `text` representation is available for all\ndocument file types in Box using the `[extracted_text]`\nrepresentation.\n\n`x-rep-hints: [extracted_text]`',
            example: '[pdf]',
            in: 'header',
            name: 'x-rep-hints',
            required: true,
            schema: { nullable: true, type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returns a file object.\n\nNot all available fields are returned by default. Use the\n[fields](#param-fields) query parameter to explicitly request\nany specific fields.',
      content: { 'application/json': { schema: FileSchema } },
    },
    304: {
      description:
        'Returns an empty response when the `If-None-Match` header matches\nthe current `etag` value of the folder. This indicates that the folder\nhas not changed since it was last requested.',
    },
    401: {
      description:
        'Returned when the access token provided in the `Authorization` header\nis not recognized or not provided.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    404: {
      description:
        'Returned if the file is not found, or the user does not\nhave access to the file.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    405: {
      description: 'Returned if the `file_id` is not in a recognized format.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    415: {
      description:
        'Returns an error if an action is performed on a file with an\nincorrect media type.\n\n* `unsupported_media_type` when requesting an `expiring_embed_link`\n  for a file that is not supported by Box Embed.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

