export const getFilesFileIdContentRoute = createRoute({
  method: 'get',
  path: '/files/{file_id}/content',
  tags: ['Downloads'],
  summary: 'Download file',
  description: 'Returns the contents of a file in binary format.',
  operationId: 'get_files_id_content',
  request: {
    params: z.object({
      file_id: z
        .string()
        .openapi({
          param: {
            description:
              'The unique identifier that represents a file.\n\nThe ID for any file can be determined\nby visiting a file in the web application\nand copying the ID from the URL. For example,\nfor the URL `https://*.app.box.com/files/123`\nthe `file_id` is `123`.',
            example: '12345',
            in: 'path',
            name: 'file_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    headers: z.object({
      range: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The byte range of the content to download.\n\nThe format `bytes={start_byte}-{end_byte}` can be used to specify\nwhat section of the file to download.',
            example: 'bytes=0-1024',
            in: 'header',
            name: 'range',
            required: false,
            schema: { type: 'string' },
          },
        }),
      boxapi: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The URL, and optional password, for the shared link of this item.\n\nThis header can be used to access items that have not been\nexplicitly shared with a user.\n\nUse the format `shared_link=[link]` or if a password is required then\nuse `shared_link=[link]&shared_link_password=[password]`.\n\nThis header can be used on the file or folder shared, as well as on any files\nor folders nested within the item.',
            example: 'shared_link=[link]&shared_link_password=[password]',
            in: 'header',
            name: 'boxapi',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      version: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The file version to download',
            example: '4',
            in: 'query',
            name: 'version',
            required: false,
            schema: { type: 'string' },
          },
        }),
      access_token: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'An optional access token that can be used to pre-authenticate this request, which means that a download link can be shared with a browser or a third party service without them needing to know how to handle the authentication.\nWhen using this parameter, please make sure that the access token is sufficiently scoped down to only allow read access to that file and no other files or folders.',
            example: 'c3FIOG9vSGV4VHo4QzAyg5T1JvNnJoZ3ExaVNyQWw6WjRsanRKZG5lQk9qUE1BVQ',
            in: 'query',
            name: 'access_token',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    202: {
      description:
        'If the file is not ready to be downloaded yet `Retry-After` header will\nbe returned indicating the time in seconds after which the file will\nbe available for the client to download.\n\nThis response can occur when the file was uploaded immediately before the\ndownload request.',
      headers: z.object({
        'Retry-After': {
          description: 'The time in seconds after which to retry the download',
          schema: z
            .int()
            .exactOptional()
            .openapi({
              description: 'The time in seconds after which to retry the download',
              param: { required: false },
            }),
        },
      }),
    },
    302: {
      description:
        'If the file is available to be downloaded the response will include a\n`Location` header for the file on `dl.boxcloud.com`.\n\nThe `dl.boxcloud.com` URL is not persistent and clients will need\nto follow the redirect in order to actually download the file.',
      headers: z.object({
        Location: {
          description: 'A pointer to the download URL',
          schema: z
            .url()
            .exactOptional()
            .openapi({ description: 'A pointer to the download URL', param: { required: false } }),
        },
      }),
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

export const postFilesFileIdContentRoute = createRoute({
  method: 'post',
  path: '/files/{file_id}/content',
  tags: ['Uploads'],
  summary: 'Upload file version',
  description:
    "Update a file's content. For file sizes over 50MB we recommend\nusing the Chunk Upload APIs.\n\n# Request body order\n\nThe `attributes` part of the body must come **before** the\n`file` part. Requests that do not follow this format when\nuploading the file will receive a HTTP `400` error with a\n`metadata_after_file_contents` error code.",
  operationId: 'post_files_id_content',
  request: {
    params: z.object({
      file_id: z
        .string()
        .openapi({
          param: {
            description:
              'The unique identifier that represents a file.\n\nThe ID for any file can be determined\nby visiting a file in the web application\nand copying the ID from the URL. For example,\nfor the URL `https://*.app.box.com/files/123`\nthe `file_id` is `123`.',
            example: '12345',
            in: 'path',
            name: 'file_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    headers: z.object({
      'if-match': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "Ensures this item hasn't recently changed before\nmaking changes.\n\nPass in the item's last observed `etag` value\ninto this header and the endpoint will fail\nwith a `412 Precondition Failed` if it\nhas changed since.",
            example: '1',
            in: 'header',
            name: 'if-match',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'content-md5': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'An optional header containing the SHA1 hash of the file to\nensure that the file was not corrupted in transit.',
            example: '134b65991ed521fcfe4724b7d814ab8ded5185dc',
            in: 'header',
            name: 'content-md5',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.',
            example: ['id', 'type', 'name'],
            explode: false,
            in: 'query',
            name: 'fields',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
          },
        }),
    }),
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              attributes: z
                .object({
                  content_modified_at: z.iso
                    .datetime({ offset: true })
                    .exactOptional()
                    .openapi({
                      description:
                        'Defines the time the file was last modified at.\n\nIf not set, the upload time will be used.',
                      example: '2012-12-12T10:53:43-08:00',
                    }),
                  name: z
                    .string()
                    .openapi({
                      description:
                        'An optional new name for the file. If specified, the file\nwill be renamed when the new version is uploaded.',
                      example: 'Photo 2.0.png',
                    }),
                })
                .openapi({
                  description:
                    'The additional attributes of the file being uploaded. Mainly the\nname and the parent folder. These attributes are part of the multi\npart request body and are in JSON format.\n\n<Message warning>\n\n  The `attributes` part of the body must come **before** the\n  `file` part. Requests that do not follow this format when\n  uploading the file will receive a HTTP `400` error with a\n  `metadata_after_file_contents` error code.\n\n</Message>',
                  required: ['name'],
                }),
              file: z
                .file()
                .openapi({
                  type: 'string',
                  format: 'binary',
                  description:
                    'The content of the file to upload to Box.\n\n<Message warning>\n\n  The `attributes` part of the body must come **before** the\n  `file` part. Requests that do not follow this format when\n  uploading the file will receive a HTTP `400` error with a\n  `metadata_after_file_contents` error code.\n\n</Message>',
                }),
            })
            .openapi({ required: ['attributes', 'file'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Returns the new file object in a list.',
      content: { 'application/json': { schema: FilesSchema } },
    },
    412: {
      description:
        'Returns an error when the `If-Match` header does not match\nthe current `etag` value of the file. This indicates that the file\nhas changed since it was last requested.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
  servers: [{ description: 'Server for file uploads', url: 'https://upload.box.com/api/2.0' }],
})

