export const putFilesFileIdMetadataScopeTemplateKeyRoute = createRoute({
  method: 'put',
  path: '/files/{file_id}/metadata/{scope}/{template_key}',
  tags: ['Metadata instances (Files)'],
  summary: 'Update metadata instance on file',
  description:
    'Updates a piece of metadata on a file.\n\nThe metadata instance can only be updated if the template has already been\napplied to the file before. When editing metadata, only values that match\nthe metadata template schema will be accepted.\n\nThe update is applied atomically. If any errors occur during the\napplication of the operations, the metadata instance will not be changed.',
  operationId: 'put_files_id_metadata_id_id',
  request: {
    params: z.object({
      file_id: z
        .string()
        .openapi({
          param: {
            description:
              'The unique identifier that represents a file.\n\nThe ID for any file can be determined\nby visiting a file in the web application\nand copying the ID from the URL. For example,\nfor the URL `https://*.app.box.com/files/123`\nthe `file_id` is `123`.',
            example: '12345',
            in: 'path',
            name: 'file_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
      scope: z
        .enum(['global', 'enterprise'])
        .openapi({
          param: {
            description: 'The scope of the metadata template',
            example: 'global',
            in: 'path',
            name: 'scope',
            required: true,
            schema: { enum: ['global', 'enterprise'], type: 'string' },
          },
        }),
      template_key: z
        .string()
        .openapi({
          param: {
            description: 'The name of the metadata template',
            example: 'properties',
            in: 'path',
            name: 'template_key',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json-patch+json': {
          schema: z
            .array(
              z
                .object({
                  from: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'The location in the metadata JSON object to move or copy a value\nfrom. Required for `move` or `copy` operations and must be in the\nformat of a [JSON-Pointer](https://tools.ietf.org/html/rfc6901).',
                      example: '/nextState',
                    }),
                  op: z
                    .enum(['add', 'replace', 'remove', 'test', 'move', 'copy'])
                    .exactOptional()
                    .openapi({
                      description:
                        'The type of change to perform on the template. Some\nof these are hazardous as they will change existing templates.',
                      example: 'add',
                    }),
                  path: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'The location in the metadata JSON object\nto apply the changes to, in the format of a\n[JSON-Pointer](https://tools.ietf.org/html/rfc6901).\n\nThe path must always be prefixed with a `/` to represent the root\nof the template. The characters `~` and `/` are reserved\ncharacters and must be escaped in the key.',
                      example: '/currentState',
                    }),
                  value: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'The value to be set or tested.\n\nRequired for `add`, `replace`, and `test` operations. For `add`,\nif the value exists already the previous value will be overwritten\nby the new value. For `replace`, the value must exist before\nreplacing.\n\nFor `test`, the existing value at the `path` location must match\nthe specified value.',
                      example: 'reviewed',
                    }),
                })
                .openapi({
                  description:
                    'A [JSON-Patch](https://tools.ietf.org/html/rfc6902) operation for a\nchange to make to the metadata instance.',
                  title: 'A metadata instance update operation',
                  required: [],
                }),
            )
            .openapi({
              description:
                'A [JSON-Patch](https://tools.ietf.org/html/rfc6902)\nspecification for the changes to make to the metadata\ninstance.\n\nThe changes are represented as a JSON array of\noperation objects.',
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description:
        'Returns the updated metadata template instance, with the\ncustom template data included.',
      content: { 'application/json': { schema: MetadataSchema } },
    },
    400: {
      description:
        'Returns an error when the request body is not valid.\n\n* `bad_request` - The request body format is not an array of valid JSON\nPatch objects.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    500: {
      description:
        'Returns an error in some edge cases when the request body is not a valid\narray of JSON Patch items.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

