export const getFilesFileIdThumbnailExtensionRoute = createRoute({
  method: 'get',
  path: '/files/{file_id}/thumbnail.{extension}',
  tags: ['Files'],
  summary: 'Get file thumbnail',
  description:
    'Retrieves a thumbnail, or smaller image representation, of a file.\n\nSizes of `32x32`,`64x64`, `128x128`, and `256x256` can be returned in\nthe `.png` format and sizes of `32x32`, `160x160`, and `320x320`\ncan be returned in the `.jpg` format.\n\nThumbnails can be generated for the image and video file formats listed\n[found on our community site][1].\n\n[1]: https://community.box.com/t5/Migrating-and-Previewing-Content/File-Types-and-Fonts-Supported-in-Box-Content-Preview/ta-p/327',
  operationId: 'get_files_id_thumbnail_id',
  request: {
    params: z.object({
      file_id: z
        .string()
        .openapi({
          param: {
            description:
              'The unique identifier that represents a file.\n\nThe ID for any file can be determined\nby visiting a file in the web application\nand copying the ID from the URL. For example,\nfor the URL `https://*.app.box.com/files/123`\nthe `file_id` is `123`.',
            example: '12345',
            in: 'path',
            name: 'file_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
      extension: z
        .enum(['png', 'jpg'])
        .openapi({
          param: {
            description: 'The file format for the thumbnail',
            example: 'png',
            in: 'path',
            name: 'extension',
            required: true,
            schema: { enum: ['png', 'jpg'], type: 'string' },
          },
        }),
    }),
    query: z.object({
      min_height: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(32).max(320),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The minimum height of the thumbnail',
            example: 32,
            in: 'query',
            name: 'min_height',
            schema: { maximum: 320, minimum: 32, type: 'integer' },
            required: false,
          },
        }),
      min_width: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(32).max(320),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The minimum width of the thumbnail',
            example: 32,
            in: 'query',
            name: 'min_width',
            schema: { maximum: 320, minimum: 32, type: 'integer' },
            required: false,
          },
        }),
      max_height: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(32).max(320),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum height of the thumbnail',
            example: 320,
            in: 'query',
            name: 'max_height',
            required: false,
            schema: { maximum: 320, minimum: 32, type: 'integer' },
          },
        }),
      max_width: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(32).max(320),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum width of the thumbnail',
            example: 320,
            in: 'query',
            name: 'max_width',
            required: false,
            schema: { maximum: 320, minimum: 32, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'When a thumbnail can be created the thumbnail data will be\nreturned in the body of the response.',
      content: {
        'image/jpg': {
          schema: z
            .file()
            .openapi({ type: 'string', format: 'binary', description: 'The thumbnail' }),
        },
        'image/png': {
          schema: z
            .file()
            .openapi({ type: 'string', format: 'binary', description: 'The thumbnail' }),
        },
      },
    },
    202: {
      description:
        'Sometimes generating a thumbnail can take a few seconds. In these\nsituations the API returns a `Location`-header pointing to a\nplaceholder graphic for this file type.\n\nThe placeholder graphic can be used in a user interface until the\nthumbnail generation has completed. The `Retry-After`-header indicates\nwhen to the thumbnail will be ready. At that time, retry this endpoint\nto retrieve the thumbnail.',
      headers: z.object({
        Location: {
          description:
            'A pointer to a placeholder graphic that can be used until the\nthumbnail has been generated.',
          schema: z
            .url()
            .exactOptional()
            .openapi({
              description:
                'A pointer to a placeholder graphic that can be used until the\nthumbnail has been generated.',
              param: { required: false },
            }),
        },
        'Retry-After': {
          description:
            'The time in seconds after which the thumbnail will be available.\n\nYour application  only attempt to get the thumbnail again after\nthis time.',
          schema: z
            .preprocess(
              (val) =>
                typeof val === 'number' && Number.isSafeInteger(val)
                  ? BigInt(val)
                  : typeof val === 'string' && /^-?\d+$/.test(val)
                    ? BigInt(val)
                    : val,
              z.int64(),
            )
            .exactOptional()
            .openapi({
              description:
                'The time in seconds after which the thumbnail will be available.\n\nYour application  only attempt to get the thumbnail again after\nthis time.',
              param: { required: false },
              type: 'integer',
              format: 'int64',
            }),
        },
      }),
    },
    302: {
      description:
        'Returns an error when Box is not able to create a thumbnail for this\nfile type.\n\nInstead, a `Location`-header pointing to a placeholder graphic for\nthis file type will be returned.',
      headers: z.object({
        Location: {
          description: 'A pointer to a placeholder graphic that can be used for this\nfile type.',
          schema: z
            .url()
            .exactOptional()
            .openapi({
              description:
                'A pointer to a placeholder graphic that can be used for this\nfile type.',
              param: { required: false },
            }),
        },
      }),
    },
    400: {
      description:
        'Returns an error if some of the parameters are missing or\nnot valid.\n\n* `requested_preview_unavailable` - an incorrect dimension was\n  requested. This will happen if the dimension requested is\n  larger or smaller than the available file sizes for the thumbnail\n  format, or when when any of the size constraints contradict\n  each other.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    403: {
      description:
        'Returned when the access token provided in the `Authorization` header\nis not recognized or not provided.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    404: {
      description:
        'Returned if the file is not found, or the user does not\nhave access to the file, or for additional reasons.\n\n* `preview_cannot_be_generated` - Box does not support thumbnails\n  for this type of file',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

export const getFilesFileIdTrashRoute = createRoute({
  method: 'get',
  path: '/files/{file_id}/trash',
  tags: ['Trashed files'],
  summary: 'Get trashed file',
  description:
    'Retrieves a file that has been moved to the trash.\n\nPlease note that only if the file itself has been moved to the\ntrash can it be retrieved with this API call. If instead one of\nits parent folders was moved to the trash, only that folder\ncan be inspected using the\n[`GET /folders/:id/trash`](e://get_folders_id_trash) API.\n\nTo list all items that have been moved to the trash, please\nuse the [`GET /folders/trash/items`](e://get-folders-trash-items/)\nAPI.',
  operationId: 'get_files_id_trash',
  request: {
    params: z.object({
      file_id: z
        .string()
        .openapi({
          param: {
            description:
              'The unique identifier that represents a file.\n\nThe ID for any file can be determined\nby visiting a file in the web application\nand copying the ID from the URL. For example,\nfor the URL `https://*.app.box.com/files/123`\nthe `file_id` is `123`.',
            example: '12345',
            in: 'path',
            name: 'file_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.',
            example: ['id', 'type', 'name'],
            explode: false,
            in: 'query',
            name: 'fields',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returns the file that was trashed,\nincluding information about when the it\nwas moved to the trash.',
      content: { 'application/json': { schema: TrashFileSchema } },
    },
    404: {
      description:
        "Returns an error if the file can not be found directly\nin the trash.\n\nPlease note that a `HTTP 404` is also returned if any of\nthe file's parent folders have been moved to the trash.\n\nIn that case, only that parent folder can be inspected using\nthe [`GET /folders/:id/trash`](e://get_folders_id_trash) API.",
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

