export const postGroupMembershipsRoute = createRoute({
  method: 'post',
  path: '/group_memberships',
  tags: ['Group memberships'],
  summary: 'Add user to group',
  description:
    'Creates a group membership. Only users with\nadmin-level permissions will be able to use this API.',
  operationId: 'post_group_memberships',
  request: {
    query: z.object({
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.',
            example: ['id', 'type', 'name'],
            explode: false,
            in: 'query',
            name: 'fields',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              configurable_permissions: z
                .record(
                  z.string(),
                  z
                    .boolean()
                    .openapi({
                      description: 'A key value pair of custom permissions.',
                      example: true,
                      'x-box-example-key': 'can_run_reports',
                    }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Custom configuration for the permissions an admin\nif a group will receive. This option has no effect\non members with a role of `member`.\n\nSetting these permissions overwrites the default\naccess levels of an admin.\n\nSpecifying a value of "null" for this object will disable\nall configurable permissions. Specifying permissions will set\nthem accordingly, omitted permissions will be enabled by default.',
                  example: { can_run_reports: true },
                }),
              group: z
                .object({
                  id: z
                    .string()
                    .openapi({
                      description: 'The ID of the group to add the user to',
                      example: '4545523',
                    }),
                })
                .openapi({ description: 'The group to add the user to.', required: ['id'] }),
              role: z
                .enum(['member', 'admin'])
                .exactOptional()
                .openapi({ description: 'The role of the user in the group.', example: 'member' }),
              user: z
                .object({
                  id: z
                    .string()
                    .openapi({
                      description: 'The ID of the user to add to the group',
                      example: '1434325',
                    }),
                })
                .openapi({ description: 'The user to add to the group.', required: ['id'] }),
            })
            .openapi({ required: ['user', 'group'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Returns a new group membership object.',
      content: { 'application/json': { schema: GroupMembershipSchema } },
    },
    403: {
      description:
        'Returns an error when the user cannot be added\nto a group.\n\n* `forbidden_by_policy`: Adding a user\nto a group is forbidden due to information\nbarrier restrictions.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

