export const getGroupsRoute = createRoute({
  method: 'get',
  path: '/groups',
  tags: ['Groups'],
  summary: 'List groups for enterprise',
  description:
    "Retrieves all of the groups for a given enterprise. The user\nmust have admin permissions to inspect enterprise's groups.",
  operationId: 'get_groups',
  request: {
    query: z.object({
      filter_term: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Limits the results to only groups whose `name` starts\nwith the search term.',
            example: 'Engineering',
            in: 'query',
            name: 'filter_term',
            required: false,
            schema: { type: 'string' },
          },
        }),
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.',
            example: ['id', 'type', 'name'],
            explode: false,
            in: 'query',
            name: 'fields',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            example: 1000,
            in: 'query',
            name: 'limit',
            required: false,
            schema: { format: 'int64', maximum: 1000, type: 'integer' },
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The offset of the item at which to begin the response.\n\nQueries with offset parameter value\nexceeding 10000 will be rejected\nwith a 400 response.',
            example: 1000,
            in: 'query',
            name: 'offset',
            required: false,
            schema: { default: 0, format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returns a collection of group objects. If there are no groups, an\nempty collection will be returned.',
      content: { 'application/json': { schema: GroupsSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

