export const postMetadataCascadePoliciesRoute = createRoute({
  method: 'post',
  path: '/metadata_cascade_policies',
  tags: ['Metadata cascade policies'],
  summary: 'Create metadata cascade policy',
  description:
    'Creates a new metadata cascade policy that applies a given\nmetadata template to a given folder and automatically\ncascades it down to any files within that folder.\n\nIn order for the policy to be applied a metadata instance must first\nbe applied to the folder the policy is to be applied to.',
  operationId: 'post_metadata_cascade_policies',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              folder_id: z
                .string()
                .openapi({
                  description:
                    'The ID of the folder to apply the policy to. This folder will\nneed to already have an instance of the targeted metadata\ntemplate applied to it.',
                  example: '1234567',
                }),
              scope: z
                .enum(['global', 'enterprise'])
                .openapi({
                  description:
                    'The scope of the targeted metadata template. This template will\nneed to already have an instance applied to the targeted folder.',
                  example: 'enterprise',
                }),
              templateKey: z
                .string()
                .openapi({
                  description:
                    "The key of the targeted metadata template. This template will\nneed to already have an instance applied to the targeted folder.\n\nIn many cases the template key is automatically derived\nof its display name, for example `Contract Template` would\nbecome `contractTemplate`. In some cases the creator of the\ntemplate will have provided its own template key.\n\nPlease [list the templates for an enterprise][list], or\nget all instances on a [file][file] or [folder][folder]\nto inspect a template's key.\n\n[list]: e://get-metadata-templates-enterprise\n[file]: e://get-files-id-metadata\n[folder]: e://get-folders-id-metadata",
                  example: 'productInfo',
                }),
            })
            .openapi({ required: ['folder_id', 'scope', 'templateKey'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Returns a new of metadata cascade policy',
      content: { 'application/json': { schema: MetadataCascadePolicySchema } },
    },
    400: {
      description:
        'Returns an error when any of the parameters are not in a valid format.\n\n* `bad_request` - Either the `scope`, `templateKey`, or `folder_id` are\nnot in a valid format.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    403: {
      description:
        'Returns an error when trying to apply a policy to a restricted folder, for\nexample the root folder with ID `0`.\n\n* `forbidden` - Although the folder ID was valid and the user has access\nto the folder, the policy could not be applied to this folder.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    404: {
      description:
        'Returns an error when the template or folder can not be found, or when the\nuser does not have access to the folder or template.\n\n* `instance_tuple_not_found` - The template could not be found or the user\ndoes not have access to the template.\n* `not_found` - The folder could not be found or the user\ndoes not have access to the folder.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    409: {
      description:
        'Returns an error when a policy for this folder and template is already in\nplace.\n\n* `tuple_already_exists` - A cascade policy for this combination of\n`folder_id`, `scope` and `templateKey` already exists.',
      content: { 'application/json': { schema: ConflictErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

