export const getMetadataTemplatesEnterpriseRoute = createRoute({
  method: 'get',
  path: '/metadata_templates/enterprise',
  tags: ['Metadata templates'],
  summary: 'List all metadata templates for enterprise',
  description:
    "Used to retrieve all metadata templates created to be used specifically within\nthe user's enterprise",
  operationId: 'get_metadata_templates_enterprise',
  request: {
    query: z.object({
      marker: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Defines the position marker at which to begin returning results. This is\nused when paginating using marker-based pagination.\n\nThis requires `usemarker` to be set to `true`.',
            example: 'JV9IRGZmieiBasejOG9yDCRNgd2ymoZIbjsxbJMjIs3kioVii',
            in: 'query',
            name: 'marker',
            required: false,
            schema: { type: 'string' },
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            example: 1000,
            in: 'query',
            name: 'limit',
            required: false,
            schema: { format: 'int64', maximum: 1000, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returns all of the metadata templates within an enterprise\nand their corresponding schema.',
      content: { 'application/json': { schema: MetadataTemplatesSchema } },
    },
    400: {
      description: 'Returned when the request parameters are not valid.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

