export const putMetadataTemplatesScopeTemplateKeySchemaRoute = createRoute({
  method: 'put',
  path: '/metadata_templates/{scope}/{template_key}/schema',
  tags: ['Metadata templates'],
  summary: 'Update metadata template',
  description:
    'Updates a metadata template.\n\nThe metadata template can only be updated if the template\nalready exists.\n\nThe update is applied atomically. If any errors occur during the\napplication of the operations, the metadata template will not be changed.',
  operationId: 'put_metadata_templates_id_id_schema',
  request: {
    params: z.object({
      scope: z
        .enum(['global', 'enterprise'])
        .openapi({
          param: {
            description: 'The scope of the metadata template',
            example: 'global',
            in: 'path',
            name: 'scope',
            required: true,
            schema: { enum: ['global', 'enterprise'], type: 'string' },
          },
        }),
      template_key: z
        .string()
        .openapi({
          param: {
            description: 'The name of the metadata template',
            example: 'properties',
            in: 'path',
            name: 'template_key',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json-patch+json': {
          schema: z
            .array(
              z
                .object({
                  data: z
                    .record(
                      z.string(),
                      z
                        .string()
                        .openapi({
                          description: 'The value of a custom data entry.',
                          example: 'Aaron Levie',
                          'x-box-example-key': 'name',
                        }),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        'The data for the operation. This will vary depending on the\noperation being performed.',
                      example: { name: 'Aaron Levie' },
                    }),
                  enumOptionKey: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'For operations that affect a single `enum` option this defines\nthe key of the option that is affected.',
                      example: 'option1',
                    }),
                  enumOptionKeys: z
                    .array(z.string())
                    .exactOptional()
                    .openapi({
                      description:
                        'For operations that affect multiple `enum` options this defines\nthe keys of the options that are affected.',
                      example: ['option1', 'option2', 'option3'],
                    }),
                  fieldKey: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'For operations that affect a single field this defines the key of\nthe field that is affected.',
                      example: 'category',
                    }),
                  fieldKeys: z
                    .array(z.string())
                    .exactOptional()
                    .openapi({
                      description:
                        'For operations that affect multiple fields this defines the keys\nof the fields that are affected.',
                      example: ['category', 'name'],
                    }),
                  multiSelectOptionKey: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'For operations that affect a single multi select option this\ndefines the key of the option that is affected.',
                      example: 'option1',
                    }),
                  multiSelectOptionKeys: z
                    .array(z.string())
                    .exactOptional()
                    .openapi({
                      description:
                        'For operations that affect multiple multi select options this\ndefines the keys of the options that are affected.',
                      example: ['option1', 'option2', 'option3'],
                    }),
                  op: z
                    .enum([
                      'editTemplate',
                      'addField',
                      'reorderFields',
                      'addEnumOption',
                      'reorderEnumOptions',
                      'reorderMultiSelectOptions',
                      'addMultiSelectOption',
                      'editField',
                      'removeField',
                      'editEnumOption',
                      'removeEnumOption',
                      'editMultiSelectOption',
                      'removeMultiSelectOption',
                    ])
                    .openapi({
                      description:
                        'The type of change to perform on the template. Some\nof these are hazardous as they will change existing templates.',
                      example: 'addEnumOption',
                    }),
                })
                .openapi({
                  description:
                    'A [JSON-Patch](https://tools.ietf.org/html/rfc6902) operation for a\nchange to make to the metadata instance.',
                  required: ['op'],
                  title: 'A metadata template update operation',
                }),
            )
            .openapi({
              description:
                'A [JSON-Patch](https://tools.ietf.org/html/rfc6902)\nspecification for the changes to make to the metadata\ntemplate.\n\nThe changes are represented as a JSON array of\noperation objects.',
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description:
        'Returns the updated metadata template, with the\ncustom template data included.',
      content: { 'application/json': { schema: MetadataTemplateSchema } },
    },
    400: {
      description: 'The request body does not contain a valid metadata schema.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    403: {
      description:
        'The request body contains a scope that the user is not\nallowed to create templates for.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    404: {
      description: 'The requested template could not be found',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

