export const getShieldInformationBarriersRoute = createRoute({
  method: 'get',
  path: '/shield_information_barriers',
  tags: ['Shield information barriers'],
  summary: 'List shield information barriers',
  description: 'Retrieves a list of shield information barrier objects\nfor the enterprise of JWT.',
  operationId: 'get_shield_information_barriers',
  request: {
    query: z.object({
      marker: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Defines the position marker at which to begin returning results. This is\nused when paginating using marker-based pagination.\n\nThis requires `usemarker` to be set to `true`.',
            example: 'JV9IRGZmieiBasejOG9yDCRNgd2ymoZIbjsxbJMjIs3kioVii',
            in: 'query',
            name: 'marker',
            required: false,
            schema: { type: 'string' },
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            example: 1000,
            in: 'query',
            name: 'limit',
            required: false,
            schema: { format: 'int64', maximum: 1000, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returns a paginated list of\nshield information barrier objects,\nempty list if currently no barrier.',
      content: {
        'application/json': {
          schema: z
            .object({
              entries: z.array(ShieldInformationBarrierSchema).exactOptional(),
              limit: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description:
                    'The limit that was used for these entries.\nThis will be the same as the\n`limit` query parameter unless that\nvalue exceeded the maximum value\nallowed. The maximum value varies by API.',
                  example: 1000,
                }),
              next_marker: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'The marker for the start of the next page of results.',
                  example: 'JV9IRGZmieiBasejOG9yDCRNgd2ymoZIbjsxbJMjIs3kioVii',
                }),
            })
            .openapi({ required: [] }),
        },
      },
    },
    404: {
      description: 'Returns a `not_found` error if could not find an enterprise using JWT.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

