export const postTasksRoute = createRoute({
  method: 'post',
  path: '/tasks',
  tags: ['Tasks'],
  summary: 'Create task',
  description:
    'Creates a single task on a file. This task is not assigned to any user and\nwill need to be assigned separately.',
  operationId: 'post_tasks',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              action: z
                .enum(['review', 'complete'])
                .default('review')
                .exactOptional()
                .openapi({
                  description:
                    'The action the task assignee will be prompted to do. Must be\n\n* `review` defines an approval task that can be approved or\nrejected\n* `complete` defines a general task which can be completed',
                  example: 'review',
                }),
              completion_rule: z
                .enum(['all_assignees', 'any_assignee'])
                .default('all_assignees')
                .exactOptional()
                .openapi({
                  description:
                    'Defines which assignees need to complete this task before the task\nis considered completed.\n\n* `all_assignees` (default) requires all assignees to review or\napprove the the task in order for it to be considered completed.\n* `any_assignee` accepts any one assignee to review or\napprove the the task in order for it to be considered completed.',
                  example: 'all_assignees',
                }),
              due_at: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({
                  description: 'Defines when the task is due. Defaults to `null` if not\nprovided.',
                  example: '2012-12-12T10:53:43-08:00',
                }),
              item: z
                .object({
                  id: z
                    .string()
                    .openapi({ description: 'The ID of the file', example: '11446498' }),
                  type: z.literal('file').openapi({ description: '`file`', example: 'file' }),
                })
                .openapi({
                  description: 'The file to attach the task to.',
                  required: ['id', 'type'],
                }),
              message: z
                .string()
                .default('')
                .exactOptional()
                .openapi({
                  description: 'An optional message to include with the task.',
                  example: 'Please review',
                }),
            })
            .openapi({ required: ['item'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Returns the newly created task.',
      content: { 'application/json': { schema: TaskSchema } },
    },
    400: {
      description:
        'Returned if the request parameters or body is not valid.\n\n* `bad_request` when the body does not contain a valid request. This may\nbe because the `action` or `completion_rule` are not one of the allowed\nvalues.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    403: {
      description:
        'Returns an error when the user does not have the permission to create a\ntask on the file.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    404: {
      description:
        'Returns an error when the file could not be found or the user does not\nhave access to the file.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

