export const getUsersRoute = createRoute({
  method: 'get',
  path: '/users',
  tags: ['Users'],
  summary: 'List enterprise users',
  description:
    'Returns a list of all users for the Enterprise along with their `user_id`,\n`public_name`, and `login`.\n\nThe application and the authenticated user need to\nhave the permission to look up users in the entire\nenterprise.',
  operationId: 'get_users',
  request: {
    query: z.object({
      filter_term: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "Limits the results to only users who's `name` or\n`login` start with the search term.\n\nFor externally managed users, the search term needs\nto completely match the in order to find the user, and\nit will only return one user at a time.",
            example: 'john',
            in: 'query',
            name: 'filter_term',
            required: false,
            schema: { type: 'string' },
          },
        }),
      user_type: z
        .enum(['all', 'managed', 'external'])
        .exactOptional()
        .openapi({
          param: {
            description:
              'Limits the results to the kind of user specified.\n\n* `all` returns every kind of user for whom the\n  `login` or `name` partially matches the\n  `filter_term`. It will only return an external user\n  if the login matches the `filter_term` completely,\n  and in that case it will only return that user.\n* `managed` returns all managed and app users for whom\n  the `login` or `name` partially matches the\n  `filter_term`.\n* `external` returns all external users for whom the\n  `login` matches the `filter_term` exactly.',
            example: 'managed',
            in: 'query',
            name: 'user_type',
            required: false,
            schema: { enum: ['all', 'managed', 'external'], type: 'string' },
          },
        }),
      external_app_user_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Limits the results to app users with the given\n`external_app_user_id` value.\n\nWhen creating an app user, an\n`external_app_user_id` value can be set. This value can\nthen be used in this endpoint to find any users that\nmatch that `external_app_user_id` value.',
            example: 'my-user-1234',
            in: 'query',
            name: 'external_app_user_id',
            required: false,
            schema: { type: 'string' },
          },
        }),
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.',
            example: ['id', 'type', 'name'],
            explode: false,
            in: 'query',
            name: 'fields',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The offset of the item at which to begin the response.\n\nQueries with offset parameter value\nexceeding 10000 will be rejected\nwith a 400 response.',
            example: 1000,
            in: 'query',
            name: 'offset',
            required: false,
            schema: { default: 0, format: 'int64', type: 'integer' },
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            example: 1000,
            in: 'query',
            name: 'limit',
            required: false,
            schema: { format: 'int64', maximum: 1000, type: 'integer' },
          },
        }),
      usemarker: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Specifies whether to use marker-based pagination instead of\noffset-based pagination. Only one pagination method can\nbe used at a time.\n\nBy setting this value to true, the API will return a `marker` field\nthat can be passed as a parameter to this endpoint to get the next\npage of the response.',
            example: true,
            in: 'query',
            name: 'usemarker',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      marker: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Defines the position marker at which to begin returning results. This is\nused when paginating using marker-based pagination.\n\nThis requires `usemarker` to be set to `true`.',
            example: 'JV9IRGZmieiBasejOG9yDCRNgd2ymoZIbjsxbJMjIs3kioVii',
            in: 'query',
            name: 'marker',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returns all of the users in the enterprise.',
      content: { 'application/json': { schema: UsersSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

export const postUsersRoute = createRoute({
  method: 'post',
  path: '/users',
  tags: ['Users'],
  summary: 'Create user',
  description:
    'Creates a new managed user in an enterprise. This endpoint\nis only available to users and applications with the right\nadmin permissions.',
  operationId: 'post_users',
  request: {
    query: z.object({
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.',
            example: ['id', 'type', 'name'],
            explode: false,
            in: 'query',
            name: 'fields',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              address: z
                .string()
                .max(255)
                .exactOptional()
                .openapi({
                  description: 'The user’s address',
                  example: '900 Jefferson Ave, Redwood City, CA 94063',
                }),
              can_see_managed_users: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Whether the user can see other enterprise users in their\ncontact list',
                  example: true,
                }),
              external_app_user_id: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'An external identifier for an app user, which can be used to look\nup the user. This can be used to tie user IDs from external\nidentity providers to Box users.',
                  example: 'my-user-1234',
                }),
              is_exempt_from_device_limits: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Whether to exempt the user from enterprise device limits',
                  example: true,
                }),
              is_exempt_from_login_verification: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Whether the user must use two-factor authentication',
                  example: true,
                }),
              is_external_collab_restricted: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Whether the user is allowed to collaborate with users outside\ntheir enterprise',
                  example: true,
                }),
              is_platform_access_only: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Specifies that the user is an app user.', example: true }),
              is_sync_enabled: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Whether the user can use Box Sync', example: true }),
              job_title: z
                .string()
                .max(100)
                .exactOptional()
                .openapi({ description: 'The user’s job title', example: 'CEO' }),
              language: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The language of the user, formatted in modified version of the\n[ISO 639-1](/guides/api-calls/language-codes) format.',
                  example: 'en',
                }),
              login: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The email address the user uses to log in\n\nRequired, unless `is_platform_access_only`\nis set to `true`.',
                  example: 'boss@box.com',
                }),
              name: z
                .string()
                .max(50)
                .openapi({ description: 'The name of the user', example: 'Aaron Levie' }),
              phone: z
                .string()
                .max(100)
                .exactOptional()
                .openapi({ description: 'The user’s phone number', example: '6509241374' }),
              role: z
                .enum(['coadmin', 'user'])
                .exactOptional()
                .openapi({ description: 'The user’s enterprise role', example: 'user' }),
              space_amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description:
                    'The user’s total available space in bytes. Set this to `-1` to\nindicate unlimited storage.',
                  example: 11345156112,
                }),
              status: z
                .enum(['active', 'inactive', 'cannot_delete_edit', 'cannot_delete_edit_upload'])
                .exactOptional()
                .openapi({ description: "The user's account status", example: 'active' }),
              timezone: z
                .string()
                .exactOptional()
                .openapi({ description: "The user's timezone", example: 'Africa/Bujumbura' }),
              tracking_codes: z
                .array(TrackingCodeSchema)
                .exactOptional()
                .openapi({
                  description:
                    'Tracking codes allow an admin to generate reports from the\nadmin console and assign an attribute to a specific group\nof users. This setting must be enabled for an enterprise before it\ncan be used.',
                }),
            })
            .openapi({ required: ['name'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Returns a user object for the newly created user.',
      content: { 'application/json': { schema: UserSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

