export const putUsersUserIdFolders0Route = createRoute({
  method: 'put',
  path: '/users/{user_id}/folders/0',
  tags: ['Transfer folders'],
  summary: 'Transfer owned folders',
  description:
    "Move all of the items (files, folders and workflows) owned by a user into\nanother user's account\n\nOnly the root folder (`0`) can be transferred.\n\nFolders can only be moved across users by users with administrative\npermissions.\n\nAll existing shared links and folder-level collaborations are transferred\nduring the operation. Please note that while collaborations at the individual\nfile-level are transferred during the operation, the collaborations are\ndeleted when the original user is deleted.\n\nThis call will be performed synchronously which might lead to a slow response\nwhen the source user has a large number of items in all of its folders.\n\nIf the destination path has a metadata cascade policy attached to any of\nthe parent folders, a metadata cascade operation will be kicked off\nasynchronously.\n\nThere is currently no way to check for when this operation is finished.\n\nThe destination folder's name will be in the format `{User}'s Files and\nFolders`, where `{User}` is the display name of the user.\n\nTo make this API call your application will need to have the \"Read and write\nall files and folders stored in Box\" scope enabled.\n\nPlease make sure the destination user has access to `Relay` or `Relay Lite`,\nand has access to the files and folders involved in the workflows being\ntransferred.\n\nAdmins will receive an email when the operation is completed.",
  operationId: 'put_users_id_folders_0',
  request: {
    params: z.object({
      user_id: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the user.',
            example: '12345',
            in: 'path',
            name: 'user_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.',
            example: ['id', 'type', 'name'],
            explode: false,
            in: 'query',
            name: 'fields',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
          },
        }),
      notify: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Determines if users should receive email notification\nfor the action performed.',
            example: true,
            in: 'query',
            name: 'notify',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              owned_by: z
                .object({
                  id: z
                    .string()
                    .openapi({
                      description: 'The ID of the user who the folder will be\ntransferred to',
                      example: '1232234',
                    }),
                })
                .openapi({
                  description: 'The user who the folder will be transferred to',
                  required: ['id'],
                }),
            })
            .openapi({ required: ['owned_by'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Returns the information for the newly created\ndestination folder.',
      content: { 'application/json': { schema: FolderSchema } },
    },
    403: {
      description:
        'Returns an error when folder ownership cannot be\ntransferred to another user.\n\n* `forbidden_by_policy`: Returned if ownership transfer\n is forbidden due to information barrier restrictions.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

export const getUsersUserIdMembershipsRoute = createRoute({
  method: 'get',
  path: '/users/{user_id}/memberships',
  tags: ['Group memberships'],
  summary: "List user's groups",
  description:
    'Retrieves all the groups for a user. Only members of this\ngroup or users with admin-level permissions will be able to\nuse this API.',
  operationId: 'get_users_id_memberships',
  request: {
    params: z.object({
      user_id: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the user.',
            example: '12345',
            in: 'path',
            name: 'user_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            example: 1000,
            in: 'query',
            name: 'limit',
            required: false,
            schema: { format: 'int64', maximum: 1000, type: 'integer' },
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The offset of the item at which to begin the response.\n\nQueries with offset parameter value\nexceeding 10000 will be rejected\nwith a 400 response.',
            example: 1000,
            in: 'query',
            name: 'offset',
            required: false,
            schema: { default: 0, format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returns a collection of membership objects. If there are no\nmemberships, an empty collection will be returned.',
      content: { 'application/json': { schema: GroupMembershipsSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

